//! The index of diagnostic codes `selka reference --query CODE` answers.
//!
//! Every `E_*` error, `L_*` lint finding, `R_*` run-time trap and `W_*` warning the compiler or
//! its runtime can print has one row: the code, a one-line meaning and the `selka docs` guide to
//! read for it. The message printed with a diagnostic is still the precise statement of the
//! problem; this table says what the code means in general. Each group below lists its codes
//! without the prefix (search for `TRY_POSITION`, not `E_TRY_POSITION`) and `entries` joins the
//! two. `reference_test.zig` scans the compiler sources and fails when a code is printed that
//! has no row here, so the table cannot fall behind the compiler.
const ownership_rules = @import("compiler_root").compiler_language.ownership_rules;

/// One diagnostic code with its general meaning and the guide that explains it.
pub const Entry = struct {
    /// The code as printed in `error[CODE]`, for example `E_TRY_POSITION`.
    code: []const u8,
    /// What the code means in general, in one line.
    meaning: []const u8,
    /// The `selka docs` topic that covers the code.
    guide: []const u8,
    /// Every ownership rule this code may enforce; each diagnostic selects one.
    rules: []const ownership_rules.Rule = &.{},
};

/// One row of a prefix group: the code without its `E_`, `L_`, `R_` or `W_`.
const Row = struct { name: []const u8, meaning: []const u8, guide: []const u8 };

/// The `selka docs` topics the rows below point at.
const topic = struct {
    const api = "api";
    const change_review = "change-review";
    const release_docs = "release-docs";
    const build = "build";
    const bytes = "bytes";
    const contracts = "contracts";
    const effects = "effects";
    const errors = "errors";
    const fix = "fix";
    const functions = "functions";
    const io = "io";
    const memory = "memory";
    const modules = "modules";
    const records = "records";
    const sets = "sets";
    const statements = "statements";
    const stdlib = "stdlib";
    const syntax = "syntax";
    const tests = "tests";
    const text = "text";
};

