/// The group `rows` with `prefix` put back in front of every name.
fn prefixed(comptime prefix: []const u8, comptime rows: []const Row) [rows.len]Entry {
    var joined: [rows.len]Entry = undefined;
    for (rows, &joined) |row, *entry| entry.* = .{ .code = prefix ++ row.name, .meaning = row.meaning, .guide = row.guide, .rules = ownership_rules.rulesFor(prefix ++ row.name) };
    return joined;
}

/// Every diagnostic code, sorted by code.
pub const entries = all: {
    @setEvalBranchQuota(100_000);
    break :all prefixed("E_", &errors) ++ prefixed("L_", &lint) ++ prefixed("R_", &traps) ++ prefixed("W_", &warnings);
};
